# -*- coding: utf-8 -*-
"""Evaluator for the alerting-rule expression language.

    evaluate(src, env)  ->  int or bool   (raises ExprError on any problem)
"""

import sys

try:                                    # deep-ish nesting / long chains
    if sys.getrecursionlimit() < 100000:
        sys.setrecursionlimit(100000)
except Exception:                       # pragma: no cover
    pass


class ExprError(Exception):
    """kind: "syntax" | "name" | "type" | "arity" | "zero-division" | "domain"
       pos : 0-based character index into the source text."""

    def __init__(self, kind, pos, message=None):
        self.kind = kind
        self.pos = pos
        if message is None:
            message = "%s error at position %d" % (kind, pos)
        Exception.__init__(self, message)


# --------------------------------------------------------------------------
# tokenizer
# --------------------------------------------------------------------------

_TWO = ('**', '<=', '>=', '==', '!=', '&&', '||')
_ONE = frozenset('+-*/%<>!?:,()')
_WS = frozenset(' \t\n')
_DIGITS = frozenset('0123456789')
_ID_START = frozenset('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_')
_ID_REST = _ID_START | _DIGITS


def _tokenize(src):
    """Return (tokens, bad_pos).

    tokens are (kind, text, pos) with kind in int/true/false/ident/op.
    Tokenizing stops at the first character that can never belong to a valid
    expression (illegal character, or an integer literal with a leading zero);
    that index is returned as bad_pos (None when there is none).
    """
    toks = []
    n = len(src)
    i = 0
    while i < n:
        c = src[i]
        if c in _WS:
            i += 1
            continue
        if c in _DIGITS:
            j = i
            while j < n and src[j] in _DIGITS:
                j += 1
            if j - i > 1 and c == '0':          # 007 is never valid
                return toks, i
            toks.append(('int', src[i:j], i))
            i = j
            continue
        if c in _ID_START:
            j = i + 1
            while j < n and src[j] in _ID_REST:
                j += 1
            word = src[i:j]
            if word == 'true':
                toks.append(('true', word, i))
            elif word == 'false':
                toks.append(('false', word, i))
            else:
                toks.append(('ident', word, i))
            i = j
            continue
        two = src[i:i + 2]
        if two in _TWO:
            toks.append(('op', two, i))
            i += 2
            continue
        if c in _ONE:
            toks.append(('op', c, i))
            i += 1
            continue
        return toks, i                       # illegal character
    return toks, None


# --------------------------------------------------------------------------
# parser (recursive descent, precedence climbing for the binary levels)
# --------------------------------------------------------------------------

# precedence of the binary operators, lowest first; 3 and 4 are non-associative
_PREC = {'||': 1, '&&': 2, '==': 3, '!=': 3,
         '<': 4, '<=': 4, '>': 4, '>=': 4,
         '+': 5, '-': 5, '*': 6, '/': 6, '%': 6}
_NON_ASSOC = frozenset((3, 4))

_UNARY = ('-', '!')


def _apply_prefixes(prefixes, node):
    """prefixes were collected left to right; the first one is outermost."""
    for op, pos in reversed(prefixes):
        node = ('un', op, pos, node)
    return node


class _Parser(object):
    __slots__ = ('toks', 'n', 'i', 'srclen')

    def __init__(self, toks, srclen):
        self.toks = toks
        self.n = len(toks)
        self.i = 0
        self.srclen = srclen

    # ---- helpers ---------------------------------------------------------
    def _peek(self):
        if self.i < self.n:
            return self.toks[self.i]
        return None

    def _syn(self, tok):
        """Always raises: end of input -> len(src), otherwise tok's position."""
        if tok is None:
            raise ExprError('syntax', self.srclen)
        raise ExprError('syntax', tok[2])

    @staticmethod
    def _is_op(tok, *ops):
        return tok is not None and tok[0] == 'op' and tok[1] in ops

    def _expect(self, op):
        tok = self._peek()
        if not self._is_op(tok, op):
            self._syn(tok)
        self.i += 1

    # ---- grammar ---------------------------------------------------------
    def parse(self):
        node = self.parse_ternary()
        if self.i < self.n:                    # leftover token breaks the text
            self._syn(self.toks[self.i])
        return node

    def parse_ternary(self):                   # level 1, right associative
        node = self.parse_binary(0)
        chain = []
        while self._is_op(self._peek(), '?'):
            tok = self._peek()
            qpos = tok[2]
            self.i += 1
            when_true = self.parse_ternary()   # full expression
            self._expect(':')
            chain.append((qpos, node, when_true))
            node = self.parse_binary(0)
        for qpos, cond, when_true in reversed(chain):
            node = ('cond', qpos, cond, when_true, node)
        return node

    def parse_binary(self, minp):              # levels 2..7
        left = self.parse_operand()
        while True:
            tok = self._peek()
            if tok is None or tok[0] != 'op':
                break
            op = tok[1]
            p = _PREC.get(op)
            if p is None or p < minp:
                break
            self.i += 1
            right = self.parse_binary(p + 1)
            left = ('bin', op, tok[2], left, right)
            if p in _NON_ASSOC:                # equality / relational are flat
                nxt = self._peek()
                if nxt is not None and nxt[0] == 'op' and _PREC.get(nxt[1]) == p:
                    self._syn(nxt)
        return left

    def parse_operand(self):                   # levels 8 + 9 (unary, **)
        outer = []
        while True:
            tok = self._peek()
            if not self._is_op(tok, *_UNARY):
                break
            outer.append((tok[1], tok[2]))
            self.i += 1

        primaries = []         # o_0 .. o_{m-1}
        powpos = []            # position of each '**'
        inner = []             # unary prefixes following each '**'
        current = self.parse_primary()
        while self._is_op(self._peek(), '**'):
            tok = self._peek()
            powpos.append(tok[2])
            self.i += 1
            pre = []
            while True:
                t2 = self._peek()
                if not self._is_op(t2, *_UNARY):
                    break
                pre.append((t2[1], t2[2]))
                self.i += 1
            primaries.append(current)
            inner.append(pre)
            current = self.parse_primary()

        if powpos:                              # fold the ** chain to the right
            m = len(powpos)
            acc = _apply_prefixes(inner[m - 1], current)
            j = m - 1
            while j >= 1:
                acc = ('bin', '**', powpos[j], primaries[j], acc)
                acc = _apply_prefixes(inner[j - 1], acc)
                j -= 1
            acc = ('bin', '**', powpos[0], primaries[0], acc)
            current = acc

        return _apply_prefixes(outer, current)

    def parse_primary(self):                    # level 10
        tok = self._peek()
        if tok is None:
            self._syn(None)
        kind = tok[0]
        if kind == 'int':
            self.i += 1
            return ('int', int(tok[1]), tok[2])
        if kind == 'true':
            self.i += 1
            return ('bool', True, tok[2])
        if kind == 'false':
            self.i += 1
            return ('bool', False, tok[2])
        if kind == 'ident':
            name, pos = tok[1], tok[2]
            self.i += 1
            nxt = self._peek()
            if self._is_op(nxt, '('):          # function call
                self.i += 1
                args = []
                t = self._peek()
                if self._is_op(t, ')'):
                    self.i += 1
                else:
                    while True:
                        args.append(self.parse_ternary())
                        t = self._peek()
                        if self._is_op(t, ','):
                            self.i += 1
                            continue
                        if self._is_op(t, ')'):
                            self.i += 1
                            break
                        self._syn(t)
                return ('call', name, pos, args)
            return ('var', name, pos)          # plain variable
        if self._is_op(tok, '('):
            self.i += 1
            inner = self.parse_ternary()
            self._expect(')')
            return inner
        self._syn(tok)


def _parse(src):
    """Parse the whole source; returns the AST, raises ExprError('syntax')."""
    toks, bad = _tokenize(src)
    parser = _Parser(toks, len(src))
    try:
        node = parser.parse()
    except ExprError as exc:
        if bad is not None and bad < exc.pos:  # illegal text appears earlier
            raise ExprError('syntax', bad) from None
        raise
    if bad is not None:                        # expression itself was fine
        raise ExprError('syntax', bad)
    return node


# --------------------------------------------------------------------------
# evaluator (explicit work stack - no recursion on long chains)
# --------------------------------------------------------------------------

_MISSING = object()
_FUNCS = ('min', 'max', 'abs')


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_bool(v):
    return isinstance(v, bool)


def _need_ints(l, r, pos):
    if not (_is_int(l) and _is_int(r)):
        raise ExprError('type', pos)


def _trunc_div(l, r):
    q = abs(l) // abs(r)
    if (l < 0) != (r < 0):
        q = -q
    return q


def _binop(op, pos, l, r):
    if op == '+':
        _need_ints(l, r, pos)
        return l + r
    if op == '-':
        _need_ints(l, r, pos)
        return l - r
    if op == '*':
        _need_ints(l, r, pos)
        return l * r
    if op == '/':
        _need_ints(l, r, pos)
        if r == 0:
            raise ExprError('zero-division', pos)
        return _trunc_div(l, r)
    if op == '%':
        _need_ints(l, r, pos)
        if r == 0:
            raise ExprError('zero-division', pos)
        return l - _trunc_div(l, r) * r
    if op == '**':
        _need_ints(l, r, pos)
        if r < 0 or r > 1000:
            raise ExprError('domain', pos)
        return l ** r
    if op in ('<', '<=', '>', '>='):
        _need_ints(l, r, pos)
        if op == '<':
            return l < r
        if op == '<=':
            return l <= r
        if op == '>':
            return l > r
        return l >= r
    # == and !=
    if _is_int(l):
        if not _is_int(r):
            raise ExprError('type', pos)
    elif _is_bool(l):
        if not _is_bool(r):
            raise ExprError('type', pos)
    else:
        raise ExprError('type', pos)
    if op == '==':
        return l == r
    return l != r


def _run(root, env):
    vals = []
    work = [('eval', root)]
    while work:
        task = work.pop()
        tag = task[0]

        if tag == 'eval':
            node = task[1]
            k = node[0]
            if k == 'int' or k == 'bool':
                vals.append(node[1])
            elif k == 'var':
                v = env.get(node[1], _MISSING)
                if v is _MISSING:
                    raise ExprError('name', node[2])
                vals.append(v)
            elif k == 'un':
                work.append(('un_after', node[1], node[2]))
                work.append(('eval', node[3]))
            elif k == 'bin':
                op = node[1]
                if op == '&&':
                    work.append(('and_after', node[2], node[4]))
                    work.append(('eval', node[3]))
                elif op == '||':
                    work.append(('or_after', node[2], node[4]))
                    work.append(('eval', node[3]))
                else:
                    work.append(('bin_after', op, node[2]))
                    work.append(('eval', node[4]))
                    work.append(('eval', node[3]))
            elif k == 'cond':
                work.append(('cond_after', node[1], node[3], node[4]))
                work.append(('eval', node[2]))
            elif k == 'call':
                name, pos, args = node[1], node[2], node[3]
                if name != 'min' and name != 'max' and name != 'abs':
                    raise ExprError('name', pos)
                na = len(args)
                if name == 'abs':
                    if na != 1:
                        raise ExprError('arity', pos)
                elif na < 1:
                    raise ExprError('arity', pos)
                work.append(('call_after', name, pos, na))
                a = na - 1
                while a >= 0:                   # args are evaluated left to right
                    work.append(('eval', args[a]))
                    a -= 1
            else:                               # pragma: no cover
                raise AssertionError('bad node')

        elif tag == 'un_after':
            op, pos = task[1], task[2]
            v = vals.pop()
            if op == '-':
                if not _is_int(v):
                    raise ExprError('type', pos)
                vals.append(-v)
            else:
                if not _is_bool(v):
                    raise ExprError('type', pos)
                vals.append(not v)

        elif tag == 'bin_after':
            op, pos = task[1], task[2]
            r = vals.pop()
            l = vals.pop()
            vals.append(_binop(op, pos, l, r))

        elif tag == 'and_after':
            pos, rhs = task[1], task[2]
            l = vals.pop()
            if not _is_bool(l):
                raise ExprError('type', pos)
            if l:
                work.append(('eval', rhs))      # else: rhs is never evaluated
            else:
                vals.append(False)

        elif tag == 'or_after':
            pos, rhs = task[1], task[2]
            l = vals.pop()
            if not _is_bool(l):
                raise ExprError('type', pos)
            if l:
                vals.append(True)
            else:
                work.append(('eval', rhs))

        elif tag == 'cond_after':
            pos, tnode, fnode = task[1], task[2], task[3]
            c = vals.pop()
            if not _is_bool(c):
                raise ExprError('type', pos)
            work.append(('eval', tnode if c else fnode))

        elif tag == 'call_after':
            name, pos, na = task[1], task[2], task[3]
            args = [vals.pop() for _ in range(na)]
            args.reverse()
            for a in args:
                if not _is_int(a):
                    raise ExprError('type', pos)
            if name == 'min':
                vals.append(min(args))
            elif name == 'max':
                vals.append(max(args))
            else:
                vals.append(abs(args[0]))

    return vals[0]


# --------------------------------------------------------------------------
# public entry point
# --------------------------------------------------------------------------

def evaluate(src: str, env: dict):
    """Evaluate `src` in the context `env`; returns an int or a bool."""
    ast = _parse(src)                 # the whole text is checked first
    return _run(ast, env)
